local A=dofile('tests/kernel_access_harness.lua')
local n=0
local function case(name,fn,options)A.case(name,fn,options);n=n+1 end
case('initial',function(r)return r.w.getConfig(),r.a.getSettings()end)
case('whole-defaults',function(r)assert(#r.config.Whitelist.Defaults.questions==6 and r.config.Afk.Defaults.minutes==15);return r.config end)
case('raw-json-config-not-merged',function(r)r.m.seed(r.config.Whitelist.Storage.configFile,{enabled=false});local c=r.w.getConfig();assert(c.questions==nil)end)
case('cache-config-fallback',function(r)r.m.files[r.config.Whitelist.Storage.configFile]=nil;r.w.config={enabled=false};local c=r.w.getConfig();assert(c.enabled==false and #c.questions==6)end)
case('default-create',function(r)r.m.files[r.config.Whitelist.Storage.configFile]=nil;local c=r.w.getConfig();assert(c.enabled)end)
case('database-config',function(r)r.m.files[r.config.Whitelist.Storage.configFile]=nil;r.dbConfig=r.m.codec.encode({percent=90,enabled=false});return r.w.loadConfig()end)
case('malformed-database-config',function(r)r.m.files[r.config.Whitelist.Storage.configFile]=nil;r.dbConfig='not-json';return r.w.loadConfig()end)
case('legacy-config',function(r)r.m.files[r.config.Whitelist.Storage.configFile]=nil;r.legacyTables.mri_qwhitelistcfg=true
    r.legacyConfig=r.m.codec.encode({Enabled=false,Percent=80,PreExamQuestions={Enabled=true,FormatPhone=true,WebHook='fixture-hook'}})
    local c=r.w.loadConfig();assert(c.percent==80 and c.preExam.enabled==true)end)
case('no-database-defaults',function(r)r.m.files[r.config.Whitelist.Storage.configFile]=nil;r.ready=false;return r.w.loadConfig()end)
case('corrupt-json-refused',function(r)r.m.files[r.config.Whitelist.Storage.configFile]='bad';assert(not pcall(r.w.getConfig))end)
case('recovered-backup',function(r)local path=r.config.Whitelist.Storage.configFile;r.m.files[path]='bad';r.m.seed(path..'.bak',{enabled=false});assert(r.w.getConfig().enabled==false)end)
case('save-config',function(r)local ok,c=r.w.saveConfig(1,{percent=82,questions={}});assert(ok and c.percent==82 and #r.workers==1);return c end)
case('save-false',function(r)r.m.onWrite=function()return false end;local ok,why=r.w.saveConfig(1,{percent=82});assert(not ok and why=='json_save_failed')end)
case('save-numeric-zero',function(r)r.m.onWrite=function()return 0 end;assert(not r.w.saveConfig(1,{percent=82}))end)
case('save-numeric-one',function(r)r.m.onWrite=function()return 1 end;assert(r.w.saveConfig(1,{percent=82}))end)
case('save-provider-truthy-preserved',function(r)r.library.saveJsonRecovery=function()return 0 end;assert(r.w.saveConfig(1,{percent=82}))end)
case('save-strips-function',function(r)local ok,c=r.w.saveConfig(1,{extra=function()end});assert(ok and c.extra==nil)end)
case('config-rpc-broadcast',function(r)r.w.saveConfig(1,{enabled=false});r.runWorker();assert(#r.workers==1)end)
case('config-rpc-error',function(r)r.rpcHook=function()error('fixture-rpc',0)end;r.w.saveConfig(1,{enabled=false})
    local co=coroutine.create(r.workers[1]);local ok=coroutine.resume(co);assert(not ok)end)
case('start-schema',function(r)assert(r.w.start());assert(r.w.start())end)
case('start-alter-columns',function(r)r.columns=0;assert(r.w.start())end)
case('start-legacy-players',function(r)r.legacyTables.mri_qwhitelist=true;r.legacyPlayers={'OLD'};r.w.start();assert(r.records.OLD)end)
case('start-unready-still-started',function(r)r.ready=false;assert(r.w.start()and r.w.started)end)
case('start-load-error-stuck',function(r)r.library.loadJsonRecovery=function()error('fixture-load',0)end;assert(not pcall(r.w.start));assert(r.w.start()and r.w.started)end)
case('json-lock-busy',function(r)
    local co=coroutine.create(function()return r.library.withJsonLock(r.config.Whitelist.Storage.configFile,function()coroutine.yield();return true end)end)
    assert(coroutine.resume(co));local ok,why=r.w.saveConfig(1,{});assert(not ok and why=='busy');assert(coroutine.resume(co));assert(r.w.saveConfig(1,{}))
end)
case('json-lock-error-release',function(r)local save=r.library.saveJsonRecovery;r.library.saveJsonRecovery=function()error('fixture-save',0)end
    assert(not pcall(r.w.saveConfig,1,{}));r.library.saveJsonRecovery=save;assert(r.w.saveConfig(1,{}))end)
case('wl-ace-fallback',function(r)r.manage=false;r.aces.admin=true;assert(r.w.canManage(1)and not r.a.canManage(1))end)
case('console-fallback-policy',function(r)r.manage=false;assert(r.w.canManage(0)and not r.a.canManage(0))end)
case('wl-denied',function(r)r.manage=false;local ok,e=r.w.saveConfig(1,{});assert(not ok and e=='no_permission')end)
print('PASS access config differentials '..n)
